INSERT INTO reviews (product_id, shop_id, user_id, rating, title, comment, verified_purchase) VALUES
  ('40000000-0000-0000-0000-000000000001', '30000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000001', 5, 'Exquisite Chanderi drape!', 'The gold zari is subtle, rich, and truly artisanal. Wore this to an intimate family function and received countless compliments.', TRUE),
  ('40000000-0000-0000-0000-000000000009', '30000000-0000-0000-0000-000000000006', '20000000-0000-0000-0000-000000000001', 5, 'Sterling quality with beautiful patina', 'Lightweight on the ears yet makes an ornate statement. The seed pearls have a natural soft luster.', TRUE),
  ('40000000-0000-0000-0000-000000000007', '30000000-0000-0000-0000-000000000005', '20000000-0000-0000-0000-000000000001', 5, 'Best Tellicherry pepper ever tasted', 'The aroma when cracked fresh is fruity and deeply complex. Elevates simple eggs and roasted potatoes completely.', TRUE)
